export type Priority = "low" | "medium" | "high";

export interface Ticket {
  id: number;
  title: string;
  priority: Priority;
  description: string;
}

const tickets: Ticket[] = [
  {
    id: 1,
    title: "Set up CI pipeline",
    priority: "high",
    description: "Configure the continuous integration pipeline for the repo.",
  },
  {
    id: 2,
    title: "Write onboarding docs",
    priority: "low",
    description: "Document the local development setup for new engineers.",
  },
];

let nextId = 3;

export function listTickets(): Ticket[] {
  return tickets.map((t) => ({ ...t }));
}

export function addTicket(data: Omit<Ticket, "id">): Ticket {
  const ticket: Ticket = { id: nextId++, ...data };
  tickets.push(ticket);
  return ticket;
}

import { component$, isDev } from "@builder.io/qwik";
import { QwikCityProvider, RouterOutlet } from "@builder.io/qwik-city";
import { RouterHead } from "./components/router-head/router-head";

import "./global.css";

export default component$(() => {
  /**
   * The root of a QwikCity site always start with the <QwikCityProvider> component,
   * immediately followed by the document's <head> and <body>.
   *
   * Don't remove the `<head>` and `<body>` elements.
   */

  return (
    <QwikCityProvider>
      <head>
        <meta charset="utf-8" />
        {!isDev && (
          <link
            rel="manifest"
            href={`${import.meta.env.BASE_URL}manifest.json`}
          />
        )}
        <RouterHead />
      </head>
      <body lang="en">
        <RouterOutlet />
      </body>
    </QwikCityProvider>
  );
});
